use std::sync::Mutex;

use wado_cli::kiln_driver::{GeneratorProvider, ProviderError, run_pipeline};
use wado_compiler::compiler_host::{
    CompilerHost, Diagnostic, GeneratorOutputFile, GeneratorRequest, GeneratorResponse,
    GeneratorRunnerError, SourceError,
};
use wado_compiler::kiln::GeneratorModule;
use wado_manifest::Manifest;

struct P;
impl GeneratorProvider for P {
    async fn get_component(&self, _: &GeneratorModule) -> Result<Vec<u8>, ProviderError> {
        Ok(b"c".to_vec())
    }
}

struct H {
    resp: Mutex<Vec<(String, GeneratorResponse)>>,
    runs: Mutex<u32>,
}
impl CompilerHost for H {
    async fn load_source(&self, path: &str) -> Result<Vec<u8>, SourceError> {
        Ok(format!("content of {path}").into_bytes())
    }
    fn emit_diagnostic(&self, _d: Diagnostic) {}
    async fn run_generator(
        &self,
        _w: &[u8],
        req: GeneratorRequest,
    ) -> Result<GeneratorResponse, GeneratorRunnerError> {
        *self.runs.lock().unwrap() += 1;
        let v = self.resp.lock().unwrap();
        Ok(v.iter().find(|(k, _)| *k == req.primary.path).unwrap().1.clone())
    }
}

fn resp(path: &str) -> GeneratorResponse {
    GeneratorResponse {
        files: vec![GeneratorOutputFile {
            path: path.to_string(),
            content: "pub fn x() {}\n".to_string(),
            is_entry: true,
        }],
        reads: vec![],
    }
}

fn host(r: Vec<(&str, GeneratorResponse)>) -> H {
    H {
        resp: Mutex::new(r.into_iter().map(|(k, v)| (k.to_string(), v)).collect()),
        runs: Mutex::new(0),
    }
}

fn rt() -> tokio::runtime::Runtime {
    tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()
}

#[test]
fn dot_slash_output_is_deleted_by_reconcile() {
    let tmp = tempfile::tempdir().unwrap();
    let m: Manifest = r#"
[package]
name = "h"
version = "0.1.0"
[registries]
default = "https://wa.dev"
[build-dependencies]
proto = { package = "ns:proto", version = "^1.0.0" }
[build.generators.g]
module = "ns:proto@1.0.0"
from = "s.proto"
"#
    .parse()
    .unwrap();
    let h = host(vec![("s.proto", resp("./lib.wado"))]);
    let out = rt().block_on(run_pipeline(&m, tmp.path(), &h, &P)).unwrap();
    println!("outcome = {out:?}");
    assert!(
        tmp.path().join("build/kiln/g/lib.wado").exists(),
        "freshly generated file was deleted: {:?}",
        out.deleted
    );
}

