#[test]
fn filesystem_host_escapes_root_and_reports_io_not_notfound() {
    let tmp = tempfile::tempdir().unwrap();
    let root = tmp.path().join("proj");
    std::fs::create_dir_all(&root).unwrap();
    std::fs::write(tmp.path().join("secret.txt"), b"SECRET").unwrap();
    let host = wado_cli::FilesystemCompilerHost::silent(root);
    let rt = tokio::runtime::Builder::new_current_thread().build().unwrap();
    let outside = rt.block_on(host.load_source("../secret.txt"));
    let missing = rt.block_on(host.load_source("nope.proto"));
    println!("outside = {:?}", outside.as_ref().map(|b| String::from_utf8_lossy(b).to_string()));
    println!("missing = {missing:?}");
    assert!(outside.is_err(), "read escaped project root");
}
